function tex(base,dark,rx=4,ry=4,grain=8000){const c=document.createElement('canvas');c.width=c.height=512;const x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,512,512);for(let i=0;i<grain;i++){x.fillStyle=`rgba(${dark},${.02+Math.random()*.12})`;const s=.4+Math.random()*2.4;x.fillRect(Math.random()*512,Math.random()*512,s,s)}for(let i=0;i<90;i++){x.strokeStyle=`rgba(${dark},${.02+Math.random()*.05})`;x.lineWidth=.4+Math.random()*1.2;x.beginPath();x.moveTo(0,Math.random()*512);x.bezierCurveTo(130,Math.random()*512,380,Math.random()*512,512,Math.random()*512);x.stroke()}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(rx,ry);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());return t}
