function M(g,m,x=0,y=0,z=0){const o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;return o}
function beam(a,b,r,m,seg=12){const q=M(new THREE.CylinderGeometry(r,r*1.05,a.distanceTo(b),seg),m);q.position.copy(a.clone().add(b).multiplyScalar(.5));q.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),b.clone().sub(a).normalize());return q}

