function getFarmLeafTexture(){if(farmLeafTexture)return farmLeafTexture;const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.clearRect(0,0,256,256);const grad=x.createRadialGradient(128,126,18,128,128,116);grad.addColorStop(0,'rgba(255,255,255,.98)');grad.addColorStop(.62,'rgba(255,255,255,.91)');grad.addColorStop(.88,'rgba(255,255,255,.5)');grad.addColorStop(1,'rgba(255,255,255,0)');x.fillStyle=grad;x.beginPath();for(let i=0;i<64;i++){const a=i/64*Math.PI*2;const r=90+Math.sin(a*5)*13+Math.sin(a*9+1.7)*8+Math.sin(a*13+.8)*5;const px=128+Math.cos(a)*r,py=128+Math.sin(a)*r*.82;if(i===0)x.moveTo(px,py);else x.lineTo(px,py)}x.closePath();x.fill();farmLeafTexture=new THREE.CanvasTexture(c);farmLeafTexture.colorSpace=THREE.SRGBColorSpace;farmLeafTexture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());return farmLeafTexture}
