function addGroundDetails(){
  let seed=918273;const rnd=()=>((seed=Math.imul(seed^seed>>>15,1|seed))>>>0)/4294967296;
  const avoid=(x,z)=>Math.abs(x-1.6)<2.6||Math.abs(z-5.2)<1.8||(x>-15&&x<-7&&z>-4&&z<4.5)||(x>4&&x<17&&z>-9&&z<4)||(x>-9&&x<-3.5&&z>-5.5&&z<4)||((x+10.2)**2/24+(z+7.4)**2/10<1.35);
  const bladeGeo=new THREE.PlaneGeometry(.032,.23),bladeMat=new THREE.MeshStandardMaterial({color:0x628c47,roughness:1,side:THREE.DoubleSide});const blades=new THREE.InstancedMesh(bladeGeo,bladeMat,2200),o=new THREE.Object3D();
  for(let i=0;i<2200;i++){let x=-20+rnd()*40,z=-14+rnd()*28;if(avoid(x,z)){i--;continue}const sc=.58+rnd()*.78;o.position.set(x,.105,z);o.rotation.set(0,rnd()*Math.PI,(-.18+rnd()*.36));o.scale.set(sc,sc*(.75+rnd()*.65),sc);o.updateMatrix();blades.setMatrixAt(i,o.matrix)}blades.castShadow=false;blades.receiveShadow=false;outside.add(blades);
  const flowerColors=[0xf2cf52,0xf4a6b8,0xb8a0df,0xf7eee1,0xe37e6d];for(let i=0;i<120;i++){let x=-19+rnd()*38,z=-13+rnd()*26;if(avoid(x,z)){i--;continue}const stem=M(new THREE.CylinderGeometry(.012,.017,.28,5),mat(0x3f6f37,1),x,.14,z),petal=M(new THREE.IcosahedronGeometry(.045+rnd()*.025,1),mat(flowerColors[i%flowerColors.length],.8),x,.3,z);outside.add(stem,petal)}
  for(let i=0;i<95;i++){let x=-19+rnd()*38,z=-13+rnd()*26;if(avoid(x,z)){i--;continue}const q=M(new THREE.DodecahedronGeometry(.055+rnd()*.11,1),stone,x,.07,z);q.scale.set(1+rnd(),.45+rnd()*.45,.7+rnd()*.7);q.rotation.y=rnd()*Math.PI;outside.add(q)}
}
