  // Mesa de centro.
  inside.add(M(rb(2.1,.16,1.05,.07),trim,-2,.55,1.5));for(const x of [-.82,.82])for(const z of [1.15,1.85])inside.add(M(new THREE.CylinderGeometry(.045,.055,.55,10),trim,-2+x,.28,z))
  // Estante, livros e planta.
