function labelSprite(text,color){const c=document.createElement('canvas');c.width=360;c.height=86;const x=c.getContext('2d');x.font='800 27px system-ui';x.textAlign='center';x.textBaseline='middle';x.fillStyle='rgba(255,255,255,.82)';x.beginPath();x.roundRect(12,10,336,66,22);x.fill();x.strokeStyle='rgba(90,65,45,.16)';x.lineWidth=2;x.stroke();x.fillStyle=color;x.fillText(text,180,43);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:t,transparent:true,depthTest:false,opacity:.94}));sp.scale.set(1.65,.4,1);return sp}
function fallbackHuman(key){const g=new THREE.Group(),skin=mat(0xe8b78e,.8),cloth=mat(key==='isa'?0xdb5b8e:0x4f91d2,.75),dark=mat(0x382923,.9);const body=M(new THREE.CapsuleGeometry(.24,.65,8,18),cloth,0,1.05,0);g.add(body);g.add(M(new THREE.SphereGeometry(.28,24,18),skin,0,1.72,0));for(const x of [-.15,.15])g.add(M(new THREE.CylinderGeometry(.05,.065,.65,10),dark,x,.48,0));return g}
function makePlayer(key){const root=new THREE.Group();const modelRoot=new THREE.Group();root.add(modelRoot);modelRoot.add(fallbackHuman(key));const label=labelSprite(key==='isa'?'Isa':'Jogador 2',key==='isa'?'#c54b7d':'#3f79b7');label.position.y=2.55;root.add(label);outside.add(root);playerMeshes.set(key,{group:root,modelRoot,label,mixer:null,actions:{},current:'',loadedModel:false,walk:0,actionUntil:0})}
makePlayer('isa');makePlayer('primo')
const gltfLoader=new GLTFLoader()
async function installHuman(key,primary,fallback){
  const rec=playerMeshes.get(key);if(!rec)return
  let asset=null
  try{asset=await gltfLoader.loadAsync(primary)}catch{asset=await gltfLoader.loadAsync(fallback)}
  const model=SkeletonUtils.clone(asset.scene);model.scale.setScalar(key==='isa'?1.03:1.02);model.position.y=0
  model.traverse(o=>{if(o.isMesh){o.castShadow=o.receiveShadow=true;if(o.material?.clone){o.material=o.material.clone();if(o.material.color&&!/(skin|head|face|hand)/i.test(o.material.name||''))o.material.color.lerp(new THREE.Color(key==='isa'?0xc95286:0x4e88bf),.12)}}})
  rec.modelRoot.clear();rec.modelRoot.add(model);rec.loadedModel=true;rec.label.position.y=2.42;rec.actions={};rec.mixer=null
  if(asset.animations?.length){rec.mixer=new THREE.AnimationMixer(model);for(const clip of asset.animations)rec.actions[clip.name.toLowerCase()]=rec.mixer.clipAction(clip);setAnim(rec,'idle')}
}
async function loadHumans(){
  await Promise.allSettled([
    installHuman('isa','https://threejs.org/examples/models/gltf/Michelle.glb','https://threejs.org/examples/models/gltf/Soldier.glb'),
    installHuman('primo','https://threejs.org/examples/models/gltf/Soldier.glb','https://threejs.org/examples/models/gltf/Xbot.glb')
  ])
}
function setAnim(rec,name){if(!rec?.mixer)return;const wanted=rec.actions[name]||rec.actions[name==='walk'?'run':'idle']||Object.values(rec.actions)[0];if(!wanted||rec.current===name)return;for(const a of Object.values(rec.actions))a.fadeOut(.18);wanted.reset().fadeIn(.18).play();rec.current=name}
loadHumans()

function cropMesh(type,ready){const g=new THREE.Group(),green=mat(0x34783a,.84),growth=ready?1:.58;if(type==='milho'){for(const x of [-.45,0,.45]){g.add(M(new THREE.CylinderGeometry(.03,.05,1.35,10),green,x,.73,0));g.add(M(new THREE.CapsuleGeometry(.075,.21,6,10),mat(0xe7c03e,.75),x+.08,.82,.03))}}else if(type==='tomate'){for(const x of [-.36,.36]){g.add(M(new THREE.CylinderGeometry(.032,.05,.9,10),green,x,.49,0));for(const z of [-.17,.14])g.add(M(new THREE.SphereGeometry(.15,18,14),mat(0xc63c31,.7),x,.61,z))}}else if(type==='morango'){for(const x of [-.42,0,.42]){for(let i=0;i<4;i++){const l=M(new THREE.SphereGeometry(.13,14,10),green,x+(i-1.5)*.06,.32,i%2?-.08:.08);l.scale.set(1.45,.36,1);g.add(l)}const fr=M(new THREE.ConeGeometry(.12,.25,14),mat(0xd84152,.7),x,.21,.14);fr.rotation.z=Math.PI;g.add(fr)}}else{for(const x of [-.4,0,.4]){for(let i=0;i<5;i++){const l=M(new THREE.ConeGeometry(.05,.47,10),green,x,.42,0);l.rotation.z=(i-2)*.27;l.rotation.y=i*Math.PI*.4;g.add(l)}if(ready){const c=M(new THREE.ConeGeometry(.1,.38,14),mat(0xe17c2a,.72),x,.2,0);c.rotation.z=Math.PI;g.add(c)}}}g.scale.setScalar(growth);return g}
function updatePlots(){for(const p of snapshot?.plots||[]){const g=plotMeshes.get(Number(p.no));if(!g)continue;const old=g.getObjectByName('crop');if(old)g.remove(old);if(p.crop){const c=cropMesh(p.crop,p.readyAt&&Date.now()>=new Date(p.readyAt).getTime());c.name='crop';c.position.y=.28;g.add(c)}}}
function updateAnimals(){for(const a of snapshot?.animals||[]){const g=animalMeshes.get(a.key);if(g)g.userData.ready=!!(a.rewardReadyAt&&Date.now()>=new Date(a.rewardReadyAt).getTime())}}
function updatePlayers(){for(const p of snapshot?.players||[]){const rec=playerMeshes.get(p.key);if(!rec)continue;const online=!!p.online||p.key===player;rec.group.visible=online;if(p.key===player&&own.loaded){rec.group.position.set(own.x,0,own.z)}else if(locationMode==='outside'){rec.group.position.set(num(p.x),0,num(p.z))}if(rec.label.userData.name!==p.name){rec.group.remove(rec.label);rec.label=labelSprite(p.name||p.key,p.key==='isa'?'#c54b7d':'#3f79b7');rec.label.position.y=rec.loadedModel?2.4:2.55;rec.label.userData.name=p.name;rec.group.add(rec.label)}}}
function updateHud(){const isa=playerData('isa')||{},primo=playerData('primo')||{},me=playerData(player)||{};$('isaName').textContent=isa.name||'Isa';$('legendIsa').textContent=isa.name||'Isa';$('primoName').textContent=primo.name||'Jogador 2 🔒';$('isaScore').textContent=isa.score||0;$('primoScore').textContent=primo.score||0;$('sharedScore').textContent=snapshot?.room?.sharedScore||0;$('farmLevel').textContent=`nível ${snapshot?.room?.level||1}`;$('myCoins').textContent=me.coins??50;$('onlineState').textContent='🚧 teste exclusivo da Isa';updateEnergy(0)}
function applySnapshot(s){snapshot=s;updateHud();updatePlayers();updatePlots();updateAnimals()}
async function doAction(action,payload={}){if(!gameToken)return;const s=await rpc('farm_game_action',{p_token:gameToken,p_action:action,p_payload:payload});applySnapshot(s);setConnection(true,'Ao vivo');return s}
async function refresh(){if(!gameToken||pollBusy)return;pollBusy=true;try{const s=await rpc('farm_game_snapshot',{p_token:gameToken});applySnapshot(s);setConnection(true,'Ao vivo')}catch{setConnection(false,'Reconectando…')}finally{pollBusy=false}}

function markMove(){own.lastInput=Date.now();const rec=playerMeshes.get(player);if(rec)rec.group.position.set(own.x,0,own.z)}
function moveLocal(dx,dz,keepTarget=false){if(!keepTarget)own.target=null;const bx=locationMode==='outside'?15.8:5.0,bz=locationMode==='outside'?10.3:3.45;own.x=clamp(own.x+dx,-bx,bx);own.z=clamp(own.z+dz,-bz,bz);markMove();if(locationMode==='outside')queueMove()}
function queueMove(force=false){if(locationMode!=='outside'||!gameToken||own.sending)return;const now=Date.now();if(!force&&now-own.lastSent<180)return;own.lastSent=now;own.sending=true;const x=own.x,z=own.z;rpc('farm_game_action',{p_token:gameToken,p_action:'move',p_payload:{x,z}}).then(s=>{snapshot=s;updateHud();updatePlots();updateAnimals();updatePlayers();setConnection(true,'Ao vivo')}).catch(()=>setConnection(false,'Reconectando…')).finally(()=>{own.sending=false;if(Math.hypot(own.x-x,own.z-z)>.08)setTimeout(()=>queueMove(true),35)})}

function setCameraMode(mode){cameraMode=mode;orbit.enabled=mode==='orbit';stageWrap?.classList.toggle('eye-mode',mode==='eye');$('camera360Btn')?.classList.toggle('active',mode==='orbit');$('eyeCameraBtn')?.classList.toggle('active',mode==='eye');const h=$('cameraHelp');if(h){h.textContent=mode==='orbit'?'🧭 Arraste para girar 360° e use a roda para aproximar.':mode==='eye'?'👁️ Visão no nível dos olhos. Arraste para olhar ao redor.':'🎥 Câmera acompanhando o Nick.';h.classList.add('show');clearTimeout(h._t);h._t=setTimeout(()=>h.classList.remove('show'),2600)}}
$('camera360Btn')?.addEventListener('click',()=>setCameraMode(cameraMode==='orbit'?'follow':'orbit'))
$('eyeCameraBtn')?.addEventListener('click',()=>setCameraMode(cameraMode==='eye'?'follow':'eye'))

const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let pointerDown=null,draggingEye=false,lastPointer={x:0,y:0}
function setPointer(e){const r=renderer.domElement.getBoundingClientRect();pointer.x=((e.clientX-r.left)/r.width)*2-1;pointer.y=-((e.clientY-r.top)/r.height)*2+1;ray.setFromCamera(pointer,camera)}
function interactiveTarget(e){setPointer(e);const hits=ray.intersectObjects(interactive,true);for(const h of hits){let o=h.object;while(o&&o!==scene){if(o.userData?.kind)return o.userData;o=o.parent}}return null}
function groundTarget(e){setPointer(e);const target=locationMode==='outside'?ground:indoorFloor;const h=ray.intersectObject(target,false)[0];return h?.point?{x:h.point.x,z:h.point.z}:null}
renderer.domElement.addEventListener('pointerdown',e=>{renderer.domElement.focus({preventScroll:true});pointerDown={x:e.clientX,y:e.clientY};lastPointer={x:e.clientX,y:e.clientY};draggingEye=cameraMode==='eye'})
renderer.domElement.addEventListener('pointermove',e=>{if(!draggingEye||!pointerDown)return;const dx=e.clientX-lastPointer.x,dy=e.clientY-lastPointer.y;eyeYaw-=dx*.006;eyePitch=clamp(eyePitch-dy*.004,-.75,.55);lastPointer={x:e.clientX,y:e.clientY}})
renderer.domElement.addEventListener('pointerleave',()=>{draggingEye=false})

function setTool(t){selectedTool=t;document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===t))}
document.querySelectorAll('.tool').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('tipClose')?.addEventListener('click',()=>$('tipCard')?.remove())
function targetPosition(t){if(t.kind==='plot')return plotMeshes.get(Number(t.id))?.position.clone();if(t.kind==='animal')return animalMeshes.get(t.id)?.position.clone();if(t.kind==='door-enter')return new THREE.Vector3(-10.65,0,3);if(t.kind==='door-exit')return new THREE.Vector3(0,0,3.15);if(t.kind==='rest')return new THREE.Vector3(-2.75,0,.55);if(t.kind==='eat')return new THREE.Vector3(2.25,0,1.65);if(t.kind==='fishspot')return new THREE.Vector3(-7.2,0,-6.35);return null}
function dist(v){return Math.hypot(own.x-v.x,own.z-v.z)}
function approach(v){if(dist(v)<1.45)return;const d=new THREE.Vector2(own.x-v.x,own.z-v.z).normalize().multiplyScalar(1.25);own.target={x:v.x+d.x,z:v.z+d.y};own.lastInput=Date.now()}
function waitNear(v,max=6500){return new Promise(resolve=>{const st=performance.now();const tick=()=>{if(dist(v)<1.65||performance.now()-st>max)return resolve();requestAnimationFrame(tick)};tick()})}
function particle(start,end,color,count=28,size=.05,duration=750,arc=.55){const geo=new THREE.SphereGeometry(size,10,7);for(let i=0;i<count;i++){const m=M(geo,new THREE.MeshPhysicalMaterial({color,roughness:.2,transparent:true,opacity:.9,clearcoat:.3}));m.position.copy(start);scene.add(m);fx.push({m,start:start.clone(),end:end.clone(),born:performance.now()+i*14,duration,arc:arc*(.65+Math.random()*.7)})}}
function puff(pos,color=0x68442c){for(let i=0;i<18;i++){const m=M(new THREE.SphereGeometry(.055+Math.random()*.05,10,7),new THREE.MeshStandardMaterial({color,transparent:true,opacity:.68,roughness:1}),pos.x+(Math.random()-.5)*.55,.28+Math.random()*.28,pos.z+(Math.random()-.5)*.55);scene.add(m);fx.push({m,puff:true,born:performance.now(),duration:620,dx:(Math.random()-.5)*.7,dz:(Math.random()-.5)*.7})}}
function cropColor(c){return{cenoura:0xe98635,milho:0xe6c247,tomate:0xd64d3f,morango:0xdc4f5b}[c]||0xf0c85a}
function sleep(ms){return new Promise(r=>setTimeout(r,ms))}

async function enterHouse(){outdoorReturn={x:own.x,z:own.z};locationMode='inside';outside.visible=false;inside.visible=true;const me=playerMeshes.get(player);inside.add(me.group);own.x=0;own.z=3.15;own.target=null;me.group.position.set(own.x,0,own.z);$('locationLabel').textContent='🏠 Dentro de casa';setCameraMode('follow');camera.position.set(5,4.1,6.5);camera.lookAt(0,1,0);toast('🏠 Você entrou em casa. Pode sentar, comer e descansar.')}
async function exitHouse(){const me=playerMeshes.get(player);locationMode='outside';inside.visible=false;outside.visible=true;outside.add(me.group);own.x=outdoorReturn.x;own.z=outdoorReturn.z;own.target=null;me.group.position.set(own.x,0,own.z);$('locationLabel').textContent='🌾 Área externa';setCameraMode('follow');queueMove(true);toast('🌿 De volta ao trabalho na fazenda!')}
async function rest(){const rec=playerMeshes.get(player);own.target=null;own.x=-2.85;own.z=.42;rec.group.position.set(own.x,.48,own.z);rec.group.rotation.y=Math.PI/2;setAnim(rec,'idle');toast('🛋️ Descansando um pouco…',3000);await sleep(2500);updateEnergy(35);rec.group.position.y=0;toast('✨ Energia recuperada. Hora de voltar à fazenda!')}
async function eat(){const rec=playerMeshes.get(player);own.target=null;own.x=2.25;own.z=1.55;rec.group.position.set(own.x,0,own.z);rec.group.rotation.y=Math.PI;setAnim(rec,'idle');const food=M(new THREE.SphereGeometry(.12,14,10),mat(0xd45636,.55),own.x,.9,own.z-.35);inside.add(food);toast('🍎 Fazendo um lanchinho…',2600);await sleep(2200);inside.remove(food);updateEnergy(25);toast('😋 Pronto! Energia renovada.')}
async function fish(){if(locationMode!=='outside'){toast('🎣 Vá até o laguinho para pescar.');return}const p=new THREE.Vector3(-7.2,0,-6.35);approach(p);await waitNear(p);own.target=null;const rec=playerMeshes.get(player);rec.group.rotation.y=-1.75;const rod=beam(new THREE.Vector3(own.x,.95,own.z),new THREE.Vector3(-8.8,.9,-7.0),.025,darkWood,10);outside.add(rod);const lineGeo=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-8.8,.9,-7),new THREE.Vector3(-9.6,.08,-7.35)]),line=new THREE.Line(lineGeo,new THREE.LineBasicMaterial({color:0xe8edf1}));outside.add(line);toast('🎣 Esperando uma fisgada…',2600);await sleep(1700);const fish=M(new THREE.SphereGeometry(.13,14,10),mat(0xd6a05b,.5),-9.6,.12,-7.35);fish.scale.set(1.8,.65,.6);outside.add(fish);fx.push({m:fish,float:true,born:performance.now(),duration:1200});const before=num(playerData(player)?.score);await doAction('fish',{});const gain=Math.max(1,num(playerData(player)?.score)-before);updateEnergy(-3);outside.remove(rod);outside.remove(line);toast(`🐟 Pegou um peixe! +${gain} pontos e moedas.`)}

async function handleTarget(t){const p=targetPosition(t);if(t.kind==='door-enter'){approach(p);await waitNear(p);return enterHouse()}if(t.kind==='door-exit'){approach(p);await waitNear(p);return exitHouse()}if(t.kind==='rest'){approach(p);await waitNear(p);return rest()}if(t.kind==='eat'){approach(p);await waitNear(p);return eat()}if(t.kind==='fishspot'){if(selectedTool!=='fish')return toast('🎣 Escolha Pescar e clique no lago.');return fish()}if(!p)return;approach(p);await waitNear(p);own.target=null;const start=new THREE.Vector3(own.x,.95,own.z);if(t.kind==='plot'){if(selectedTool==='plant'){puff(p);particle(start,new THREE.Vector3(p.x,.4,p.z),0x4d301f,13,.04,560,.35);await doAction('plant',{plot:Number(t.id),crop:$('cropSelect').value});updateEnergy(-3);toast('🌱 Plantio concluído.')}else if(selectedTool==='water'){particle(start,new THREE.Vector3(p.x,.32,p.z),0x53b8e7,65,.042,780,.42);await doAction('water',{plot:Number(t.id)});updateEnergy(-3);toast('💧 Água caindo no canteiro.')}else if(selectedTool==='harvest'){const state=snapshot?.plots?.find(x=>Number(x.no)===Number(t.id));particle(new THREE.Vector3(p.x,.72,p.z),start,cropColor(state?.crop),25,.075,850,.85);puff(p);await doAction('harvest',{plot:Number(t.id)});updateEnergy(-5);toast('🧺 Colheita feita!')}else toast('Na horta use Plantar, Regar ou Colher.')}else if(t.kind==='animal'){if(selectedTool==='feed'){particle(start,new THREE.Vector3(p.x,.65,p.z),0xd3b24d,30,.048,730,.5);await doAction('feed',{animal:t.id});updateEnergy(-3);toast('🌾 Animal alimentado.')}else if(selectedTool==='collect'){await doAction('collect',{animal:t.id});updateEnergy(-2);toast('🥛🥚 Produto coletado!')}else toast('Nos animais use Alimentar ou Coletar.')}}
renderer.domElement.addEventListener('pointerup',async e=>{const moved=pointerDown?Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y):0;draggingEye=false;pointerDown=null;if(moved>9||cameraMode==='orbit'||actionBusy)return;const t=interactiveTarget(e);if(t){actionBusy=true;try{await handleTarget(t)}catch(err){toast(err.message||'Ainda não é possível fazer isso.')}finally{actionBusy=false};return}const g=groundTarget(e);if(g){own.target={x:g.x,z:g.z};own.lastInput=Date.now()}})

window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d'].includes(k)){e.preventDefault();keys.add(k);own.target=null}},true);window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()),true);window.addEventListener('blur',()=>keys.clear())
document.querySelectorAll('[data-move]').forEach(b=>{const d=b.dataset.move;let timer=null;const step=()=>{if(d==='up')moveLocal(0,-.44);if(d==='down')moveLocal(0,.44);if(d==='left')moveLocal(-.44,0);if(d==='right')moveLocal(.44,0)};b.addEventListener('pointerdown',e=>{e.preventDefault();step();timer=setInterval(step,110)});for(const ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>{clearInterval(timer);timer=null})})

function editNick(){const overlay=$('guestIdentity'),form=$('guestIdentityForm'),input=$('guestName'),cancel=$('identityCancel'),err=$('guestIdentityError');input.value=playerData(player)?.name||'Isa';err.textContent='';overlay.classList.remove('hidden');setTimeout(()=>input.focus(),50);const close=()=>{overlay.classList.add('hidden');form.onsubmit=null;cancel.onclick=null};cancel.onclick=close;form.onsubmit=async e=>{e.preventDefault();const name=input.value.trim();if(name.length<2){err.textContent='Digite um Nick com pelo menos 2 caracteres.';return}try{await doAction('nick',{name});close();toast('✨ Nick atualizado!')}catch(x){err.textContent=x.message||'Não foi possível salvar.'}}}
$('renameBtn')?.addEventListener('click',editNick);$('voiceBtn')?.addEventListener('click',()=>toast('🎤 O microfone multiplayer será liberado junto com o segundo jogador.'))
function resize(){const w=stage.clientWidth,h=stage.clientHeight;camera.aspect=w/Math.max(1,h);camera.updateProjectionMatrix();renderer.setSize(w,h,false)}window.addEventListener('resize',resize);resize()

async function boot(){try{if(player!=='isa')throw new Error('Fazendinha Família Feliz em construção. O segundo jogador será liberado após aprovação.');const data=await rpc('farm_game_bootstrap',{p_player:'isa',p_external_token:null,p_guest_token:null,p_guest_name:null,p_guest_avatar:null},true);gameToken=data.token;snapshot=data.snapshot;const me=playerData('isa');own.x=num(me?.x??-2);own.z=num(me?.z??4);own.loaded=true;applySnapshot(snapshot);$('loadingCard').classList.add('hidden');$('locationLabel').textContent='🌾 Área externa';setConnection(true,'Ao vivo');toast('🌄 Novo cenário carregado: 360°, visão dos olhos, casa e pesca.');setInterval(refresh,900);refresh();renderer.domElement.focus({preventScroll:true})}catch(e){$('loadingCard').innerHTML=`<strong>Não foi possível entrar</strong><span>${String(e.message||e)}</span>`;setConnection(false,'Acesso necessário')}}

function movementVector(dt){const rec=playerMeshes.get(player),speed=4.2*dt;let f=0,r=0;if(keys.has('w')||keys.has('arrowup'))f+=1;if(keys.has('s')||keys.has('arrowdown'))f-=1;if(keys.has('d')||keys.has('arrowright'))r+=1;if(keys.has('a')||keys.has('arrowleft'))r-=1;if(!f&&!r)return{x:0,z:0};const forward=new THREE.Vector3();camera.getWorldDirection(forward);forward.y=0;forward.normalize();const right=new THREE.Vector3(forward.z,0,-forward.x);const v=forward.multiplyScalar(f).add(right.multiplyScalar(r));if(v.lengthSq()>0)v.normalize().multiplyScalar(speed);if(cameraMode==='eye'&&rec)rec.group.rotation.y=Math.atan2(v.x,v.z);return{x:v.x,z:v.z}}
function updateCamera(dt){const rec=playerMeshes.get(player);if(!rec)return;const p=rec.group.position;if(cameraMode==='orbit'){orbit.target.lerp(new THREE.Vector3(p.x,p.y+1.1,p.z),.12);orbit.update();return}if(cameraMode==='eye'){const yaw=rec.group.rotation.y+eyeYaw,dir=new THREE.Vector3(Math.sin(yaw)*Math.cos(eyePitch),Math.sin(eyePitch),Math.cos(yaw)*Math.cos(eyePitch));camera.position.lerp(new THREE.Vector3(p.x,p.y+1.65,p.z),.45);camera.lookAt(camera.position.clone().add(dir));return}const yaw=rec.group.rotation.y,back=new THREE.Vector3(-Math.sin(yaw)*6.2,4.8,-Math.cos(yaw)*6.2),desired=p.clone().add(back);if(locationMode==='inside'){back.multiplyScalar(.63);back.y=3.1;desired.copy(p).add(back)}camera.position.lerp(desired,1-Math.pow(.001,dt));camera.lookAt(p.x,p.y+1.05,p.z)}

const clock=new THREE.Clock()
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.035),mv=movementVector(dt);if(mv.x||mv.z)moveLocal(mv.x,mv.z);else if(own.target){const vx=own.target.x-own.x,vz=own.target.z-own.z,d=Math.hypot(vx,vz);if(d<.07){own.target=null;if(locationMode==='outside')queueMove(true)}else{const s=Math.min(4.6*dt,d);moveLocal(vx/d*s,vz/d*s,true)}}const rec=playerMeshes.get(player);if(rec){const moving=!!(mv.x||mv.z||own.target);if(moving){const vx=mv.x||((own.target?.x??own.x)-own.x),vz=mv.z||((own.target?.z??own.z)-own.z);if(cameraMode!=='eye'&&Math.abs(vx)+Math.abs(vz)>.001)rec.group.rotation.y=Math.atan2(vx,vz);setAnim(rec,'walk')}else setAnim(rec,'idle');rec.mixer?.update(dt)}for(const [key,r] of playerMeshes)if(key!==player)r.mixer?.update(dt);for(const mixer of animalMixers)mixer.update(dt);const t=performance.now()*.001;animalMeshes.forEach(g=>{const ph=g.userData.phase||0;if(g.userData.kind==='decor'){g.rotation.y=Math.sin(t*.2+ph)*.25;g.position.x=g.userData.baseX+Math.sin(t*.17+ph)*.1;g.position.z=g.userData.baseZ+Math.cos(t*.15+ph)*.08}else g.rotation.y=Math.sin(t*.26+ph)*.12});windBlades.rotation.z-=dt*.42;for(const [i,f] of fishies.entries()){f.position.x=-10.2+Math.sin(t*.35+f.userData.phase)*2.4;f.position.z=-7.4+Math.cos(t*.29+f.userData.phase)*1.4;f.rotation.y=Math.atan2(Math.cos(t*.35+f.userData.phase),-Math.sin(t*.29+f.userData.phase))}waterMat.opacity=.79+Math.sin(t*.8)*.025;const now=performance.now();for(let i=fx.length-1;i>=0;i--){const f=fx[i],elapsed=now-f.born;if(elapsed<0)continue;const q=Math.min(1,elapsed/f.duration);if(f.puff){f.m.position.x+=f.dx*dt;f.m.position.z+=f.dz*dt;f.m.position.y+=.35*dt;f.m.material.opacity=(1-q)*.65;f.m.scale.setScalar(1+q*1.6)}else if(f.float){f.m.position.y+=.9*dt;f.m.rotation.y+=2*dt;f.m.scale.setScalar(1+Math.sin(q*Math.PI)*.35)}else{f.m.position.lerpVectors(f.start,f.end,q);f.m.position.y+=Math.sin(q*Math.PI)*f.arc}if(q>=1){scene.remove(f.m);fx.splice(i,1)}}updateCamera(dt);renderer.render(scene,camera)}
animate();boot()
